from __future__ import annotations

import secrets

__all__ = ["new_auth_token"]


def new_auth_token() -> str:
    """Generate a callback auth token that never starts with ``-``.

    Callback tokens are passed to the bridge as separate argv values
    (``--tool-callback-auth-token <token>``); older bridge CLI parsers
    reject values with a leading dash as missing flag values, so a
    ``secrets.token_urlsafe`` token starting with ``-`` (~1/64 of draws)
    intermittently broke bridge launch. Regenerating keeps full base64url
    entropy while staying compatible with every shipped bridge.
    """
    while True:
        token = secrets.token_urlsafe(32)
        if not token.startswith("-"):
            return token
